from textlesson import build
S=dict(cls=6,subj="science",subj_file="science")
build(dict(S,ch="diversity-in-the-living-world",topic="parts-of-a-plant",name_en="Parts of a plant and their jobs",name_ta="தாவரத்தின் பாகங்களும் பணிகளும்",
 objectives=["Name the main parts of a plant","Say the job of root, stem, leaf and flower"],
 story=("Uprooting a weed","Ishaan pulled a small weed from the garden. It came out with a thin white root, a green stem, a few leaves and a tiny flower.\n\"Each part looks different,\" he said. His grandmother explained, \"Each part has its own job.\""),
 explain=["The root grows in the soil. It holds the plant firmly and takes in water and minerals from the soil.","The stem carries water and minerals up to the leaves and carries food from the leaves to other parts. It also holds the leaves and flowers up to the light.","Leaves make food for the plant using sunlight, air and water. This is called photosynthesis. The flower makes seeds, which can grow into new plants."],
 terms=["root","stem","leaf","flower","photosynthesis"],
 narr=[("The root holds the plant in the soil and takes in water and minerals.","root"),("The stem carries water up and food to all parts of the plant.","stem"),("Leaves make food using sunlight, air and water. This is photosynthesis.","leaf"),("The flower makes seeds that grow into new plants.","flower")],
 ex=("What will happen to a plant if its roots are cut off?",[("Roots take in water and minerals from the soil.","This is their job."),("Without roots the plant cannot get water, and it cannot stand firmly.","Both jobs stop."),("So the plant will wilt and die.","Roots are very important.")]),
 tb=("A friend says leaves only make the plant look beautiful. How will you explain?",["Leaves make food for the plant by photosynthesis.","They use sunlight, air and water."],["Thinking leaves are only for decoration."]),
 summary=["Root holds the plant and takes in water.","Stem carries water and food.","Leaves make food; the flower makes seeds."],
 q=[("mcq",1,"r1-root","Which part takes in water from the soil?","root",[("leaf","Leaves make food."),("flower","Flowers make seeds.")],"The root absorbs water."),
    ("tf",1,"r1-leaf","Leaves make food for the plant.",True,"True."),
    ("mcq",2,"r2-stem","Which part carries water up to the leaves?","stem",[("root","Roots take in water."),("seed","A seed grows into a plant.")],"The stem carries water."),
    ("tf",2,"r2-fl","The flower makes seeds.",True,"True."),
    ("mcq",3,"r3-photo","Food making in leaves is called","photosynthesis",[("digestion","That happens in animals."),("evaporation","That is water to vapour.")],"Leaves use sunlight, air and water."),
    ("short",3,"r3-hold","Which part holds the plant firmly in the soil?",["root","roots","the root"],"The root holds the plant."),
    ("mcq",4,"r4-light","Leaves need which of these to make food?","sunlight",[("darkness","They need light."),("sand","Sand is not needed.")],"Sunlight gives energy."),
    ("tf",4,"r4-cut","A plant can grow well without any roots.",False,"False.")]))
build(dict(S,ch="methods-of-separation-in-everyday-life",topic="filtration-and-evaporation",name_en="Filtration and evaporation",name_ta="வடிகட்டலும் ஆவியாதலும்",
 objectives=["Use filtration to separate a solid from a liquid","Get salt from salt water by evaporation"],
 story=("Tea and salt","Latha poured tea through a strainer and the tea leaves stayed behind. Later at the sea she saw workers letting sea water dry in shallow pans.\nWhite salt was left behind.\n\"One way keeps the solid back and the other lets the water go,\" she said."),
 explain=["Filtration separates an insoluble solid from a liquid using a filter such as a cloth, paper or strainer. The liquid passes through and the solid stays behind. Muddy water can be filtered to make it clearer.","Evaporation separates a dissolved solid from a liquid. When salt water is heated or left in the sun, the water evaporates as vapour and the salt is left behind. This is how salt is made from sea water.","Often we use both: filter the sand away, then evaporate the water to get the dissolved salt."],
 terms=["filtration","evaporation","filter","residue","dissolved"],
 narr=[("Filtration separates an insoluble solid from a liquid using a filter. The liquid goes through.","filtration"),("Evaporation separates a dissolved solid. The water goes into air and the solid is left.","evaporation"),("Salt is made from sea water by evaporation in the Sun.","salt from sea water"),("We can use both methods one after the other.","filter then evaporate")],
 ex=("How will you get salt from a mixture of sand and salt dissolved in water?",[("First pour the mixture through a filter. The sand stays on the paper.","Filtration removes sand."),("The clear liquid is salt water.","Salt is dissolved in it."),("Heat or leave it in the sun. The water evaporates and the salt is left.","Evaporation gives the salt.")]),
 tb=("A friend says salt can be filtered out of salt water. How will you correct this?",["Salt is dissolved, so it passes through the filter with the water.","We must evaporate the water to get salt."],["Thinking a filter stops dissolved things."]),
 summary=["Filtration removes insoluble solids from liquids.","Evaporation leaves dissolved solids behind.","Both can be used together."],
 q=[("mcq",1,"r1-filt","Muddy water can be cleared by","filtration",[("evaporation","That would remove the water."),("magnet","Mud is not magnetic.")],"A filter holds back the mud."),
    ("tf",1,"r1-tea","A tea strainer is a kind of filter.",True,"True."),
    ("mcq",2,"r2-salt","Salt is obtained from sea water by","evaporation",[("sieving","Salt is dissolved."),("winnowing","That is for grain and husk.")],"The Sun evaporates the water."),
    ("tf",2,"r2-pass","Dissolved salt stays back on a filter paper.",False,"False. It passes through."),
    ("mcq",3,"r3-left","After evaporating salt water, what is left?","salt",[("sand","There was no sand."),("nothing","Salt remains.")],"Salt does not evaporate."),
    ("short",3,"r3-name","Name one thing used as a filter.",["cloth","filter paper","paper","strainer","sieve","tea strainer","net"],"Cloth and paper are filters."),
    ("mcq",4,"r4-both","To get salt from salty muddy water we first","filter, then evaporate",[("evaporate, then filter","Filter the mud first."),("only freeze","That does not separate salt.")],"Filter first, then evaporate."),
    ("tf",4,"r4-vapour","In evaporation the water changes to vapour.",True,"True.")]))
build(dict(S,ch="beyond-earth",topic="stars-and-constellations",name_en="Stars and constellations",name_ta="விண்மீன்களும் விண்மீன் கூட்டங்களும்",
 objectives=["Say that the Sun is a star","Name the Pole Star and the Saptarshi group"],
 story=("The night sky","On a dark night in the village, Pavan saw thousands of stars. His grandfather pointed to seven bright stars shaped like a big spoon.\n\"That is Saptarshi,\" he said. \"Follow its edge and you will find the Pole Star.\""),
 explain=["Stars are huge balls of hot glowing gas that make their own light. The Sun is our nearest star. Other stars look small because they are very far away.","Groups of stars that seem to form a pattern are called constellations. Examples are Saptarshi (the Great Bear or Big Dipper) and Orion.","The Pole Star stays almost in the same place in the northern sky because it is above the North Pole. Travellers used it to find north. All other stars seem to move across the sky as the Earth turns."],
 terms=["star","constellation","Pole Star","Saptarshi"],
 narr=[("Stars are giant balls of hot gas that make their own light. The Sun is a star.","stars and the Sun"),("Other stars look tiny because they are very far away.","far away"),("A group of stars forming a pattern is a constellation, like Saptarshi.","constellation"),("The Pole Star shows north and stays almost fixed in the sky.","Pole Star")],
 ex=("Why does the Sun look so much bigger than the other stars?",[("The Sun is a star like the others.","It is not special in kind."),("But it is much closer to us.","Distance changes how big it looks."),("Other stars are so far away they look like tiny dots.","Nearness makes the Sun look large.")]),
 tb=("A friend says stars twinkle because they are small lamps. How will you explain?",["Stars are huge hot balls of gas, not lamps.","They look small because they are very far away."],["Thinking stars are small."]),
 summary=["Stars make their own light; the Sun is a star.","A constellation is a pattern of stars.","The Pole Star shows north."],
 q=[("mcq",1,"r1-sun","The Sun is","a star",[("a planet","Planets do not make light."),("a moon","The Moon does not make light.")],"It is our nearest star."),
    ("tf",1,"r1-light","Stars make their own light.",True,"True."),
    ("mcq",2,"r2-far","Stars look small because they are","very far away",[("very tiny","Many are bigger than the Sun."),("made of paper","They are hot gas.")],"Distance makes them look small."),
    ("tf",2,"r2-const","A constellation is a group of stars that forms a pattern.",True,"True."),
    ("mcq",3,"r3-pole","The Pole Star shows the direction of","north",[("south","It shows north."),("east","It shows north.")],"It is above the North Pole."),
    ("short",3,"r3-name","Name one constellation.",["saptarshi","orion","great bear","big dipper","ursa major","cassiopeia","scorpius"],"Saptarshi and Orion are constellations."),
    ("mcq",4,"r4-move","Most stars seem to move across the sky because","the Earth turns",[("they run","Stars do not run."),("the Moon pushes them","The Earth's turning does it.")],"The Earth spins."),
    ("tf",4,"r4-pole","The Pole Star seems to stay in almost the same place.",True,"True.")]))
build(dict(S,ch="materials-around-us",topic="solids-liquids-and-gases",name_en="Solids, liquids and gases",name_ta="திண்மம், திரவம், வாயு",
 objectives=["Tell solids, liquids and gases apart","Give examples of each"],
 story=("The three jars","Mala had three jars. One held a stone, one held water and one looked empty but was full of air.\nShe could hold the stone, pour the water, and feel the air with a paper fan.\n\"They are all matter, but they behave differently,\" she said."),
 explain=["Everything around us is made of matter, which takes up space and has mass. Matter is usually found as solid, liquid or gas.","A solid has a fixed shape and a fixed size, like a stone or a book. A liquid has no fixed shape and takes the shape of its container, but its volume stays the same, like water or milk. A gas has no fixed shape or volume and spreads to fill the container, like air.","Solids and liquids can be seen and touched. Gases such as air can be felt as wind but cannot usually be seen."],
 terms=["matter","solid","liquid","gas","volume"],
 narr=[("Everything is matter. Matter is mostly a solid, a liquid or a gas.","matter"),("A solid has a fixed shape. A stone stays a stone.","solid"),("A liquid takes the shape of its container, like water in a glass.","liquid"),("A gas spreads out to fill the container, like air in a balloon.","gas")],
 ex=("Water is poured from a glass into a bowl. What happens to its shape and its amount?",[("Water takes the shape of the bowl.","A liquid has no fixed shape."),("The amount, or volume, of water stays the same.","Pouring does not change volume."),("So a liquid changes shape but not volume.","A gas would also spread out.")]),
 tb=("A friend says air is not matter because we cannot see it. How will you explain?",["Air takes up space, which we can show by blowing up a balloon.","Air has mass, so it is matter."],["Thinking matter must be visible."]),
 summary=["Matter is found as solid, liquid or gas.","Solids have a fixed shape; liquids take the shape of the container; gases spread out.","Air is a gas and is matter."],
 q=[("mcq",1,"r1-solid","Which has a fixed shape?","a stone",[("water","Water takes the shape of its container."),("air","Air spreads out.")],"A solid has a fixed shape."),
    ("tf",1,"r1-air","Air is a gas.",True,"True."),
    ("mcq",2,"r2-liq","A liquid","takes the shape of its container",[("has a fixed shape","That is a solid."),("fills all space","That is a gas.")],"Water takes the shape of a glass."),
    ("tf",2,"r2-matter","Matter takes up space.",True,"True."),
    ("mcq",3,"r3-gas","Which spreads to fill a container?","a gas",[("a solid","A solid keeps its shape."),("a stone","A stone is a solid.")],"A gas has no fixed shape or volume."),
    ("short",3,"r3-liq","Name one liquid.",["water","milk","oil","juice","petrol","tea","ink"],"Water and milk are liquids."),
    ("mcq",4,"r4-ball","A balloon gets bigger when you blow into it because air","takes up space",[("is a solid","Air is a gas."),("has no mass","Air has mass.")],"Air fills the balloon."),
    ("tf",4,"r4-vol","A liquid keeps the same volume when poured into a different container.",True,"True.")]))
